#!/bin/sh
# Starts a private session bus and gnome-keyring with a login keyring
# unlocked by KEYRING_PASSWORD (generated by the test).
set -eu
trap 'kill $(jobs -p) 2>/dev/null; exit 0' TERM INT
export HOME=/home/keyring XDG_RUNTIME_DIR=/tmp/keyring-run
export XDG_DATA_HOME=$HOME/.local/share XDG_CONFIG_HOME=$HOME/.config
mkdir -p "$HOME" "$XDG_RUNTIME_DIR"
chmod 700 "$XDG_RUNTIME_DIR"
dbus-daemon --config-file=/etc/scrim-keyring/bus.conf --nofork --nopidfile &
while [ ! -S "$XDG_RUNTIME_DIR/bus" ]; do sleep 0.1; done
export DBUS_SESSION_BUS_ADDRESS="unix:path=$XDG_RUNTIME_DIR/bus"
printf '%s' "$KEYRING_PASSWORD" | gnome-keyring-daemon --foreground --unlock --components=secrets &
wait
